// Regenerates mobile/src/lib/bundled-packs.ts from public/packs/{lang}/{level}.json.
// Run after adding a language or level: node scripts/generate-mobile-packs.mjs
import { readdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const packsDirectory = path.join(root, "public", "packs");
const lines = [
  "/* Generated by scripts/generate-mobile-packs.mjs – do not edit by hand. */",
  "// All public packs are bundled into the native app, so learning works fully offline from the first start.",
  "export const BUNDLED_PACKS: Record<string, () => unknown> = {",
];
const languages = (await readdir(packsDirectory, { withFileTypes: true })).filter((entry) => entry.isDirectory()).map((entry) => entry.name).sort();
for (const language of languages) {
  const files = (await readdir(path.join(packsDirectory, language))).filter((file) => file.endsWith(".json")).sort();
  for (const file of files) {
    lines.push(`  "${language.toUpperCase()}:${path.basename(file, ".json").toUpperCase()}": () => require("../../../public/packs/${language}/${file}"),`);
  }
}
lines.push("};");
await writeFile(path.join(root, "mobile", "src", "lib", "bundled-packs.ts"), `${lines.join("\n")}\n`);
console.log(`bundled-packs.ts aktualisiert (${lines.length - 4} Packs).`);

// Word pictures (mobile/assets/word-images/<word-id>.jpg, e.g. generated with scripts/generate_word_images.py).
const { existsSync } = await import("node:fs");
const imagesDirectory = path.join(root, "mobile", "assets", "word-images");
const images = existsSync(imagesDirectory) ? (await readdir(imagesDirectory)).filter((file) => /^[a-z0-9_]+\.jpg$/.test(file)).sort() : [];
const imageLines = [
  "// AUTO-GENERATED by scripts/generate-mobile-packs.mjs – do not edit.",
  "// Word pictures from mobile/assets/word-images/<word-id>.jpg (created with ComfyUI, see scripts/generate_word_images.py).",
  images.length ? "export const WORD_IMAGES: Record<string, number> = {" : "export const WORD_IMAGES: Record<string, number> = {};",
  ...images.map((file) => `  ${path.basename(file, ".jpg")}: require("../../assets/word-images/${file}"),`),
  ...(images.length ? ["};"] : []),
];
await writeFile(path.join(root, "mobile", "src", "lib", "word-images.ts"), `${imageLines.join("\n")}\n`);
console.log(`word-images.ts aktualisiert (${images.length} Bilder).`);
